def infectedCells(grid, t):
    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]
    frontier = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                seen[r][c] = True
                frontier.append((r, c))
    count = len(frontier)
    minute = 0
    while frontier and minute < t:
        nxt = []
        for y, x in frontier:
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < rows and 0 <= nx < cols and not seen[ny][nx] and grid[ny][nx] == 0:
                    seen[ny][nx] = True
                    nxt.append((ny, nx))
        count += len(nxt)
        frontier = nxt
        minute += 1
    return count
